function init_project_carousel(){return new Splide(".splide",{mediaQuery:"min",type:"loop",focus:"center",trimSpace:!1,breakpoints:{768:{focus:0}},autoWidth:!0}).mount()}function init_service_tabs(){function t(e){e=e.target.dataset.panel;document.querySelectorAll('.services .tab-panel[data-status="wake"]').forEach(e=>e.dataset.status="sleep"),document.querySelector("#"+e).dataset.status="wake"}document.querySelectorAll(".services .tabs button[data-panel]").forEach(e=>e.addEventListener("click",t))}document.addEventListener("DOMContentLoaded",()=>{init_project_carousel(),init_service_tabs()});